35	pub struct CheckAnchorsArgs {
36	    /// Retired: the files, now `--file` each, refused naming it.
37	    #[arg(value_name = "RETIRED", hide = true)]
38	    pub retired: Vec<String>,
39	
40	    /// A markdown file to check, repeatable. Default: every tracked
41	    /// `.md` in the workspace, excluding the agent repo and build
42	    /// output.
43	    #[arg(long = "file", value_name = "PATH")]
44	    pub files: Vec<PathBuf>,
45	}
46	
47	/// Inputs to the check anchors op, flat, owned, clap-free.
48	pub struct CheckAnchorsParams {
49	    pub files: Vec<PathBuf>,
50	}
51	
52	impl From<&CheckAnchorsArgs> for CheckAnchorsParams {
53	    /// Convert clap-derived args into the flat params (total).
54	    fn from(a: &CheckAnchorsArgs) -> Self {
55	        Self {
56	            files: a.files.clone(),
57	        }
58	    }
59	}
