61	impl SubcommandRunner for CheckAnchorsArgs {
62	    type Params = CheckAnchorsParams;
63	
64	    /// Refuse the retired positionals, naming `--file` once per file,
65	    /// else delegate to the `From<&CheckAnchorsArgs>` impl.
66	    fn to_params(&self) -> Result<Self::Params, String> {
67	        if !self.retired.is_empty() {
68	            return Err(crate::options_flags::retired_positional::refusal(
69	                "check anchors",
70	                &self.retired.join(" --file "),
71	                "--file",
72	            ));
73	        }
74	        Ok(CheckAnchorsParams::from(self))
75	    }
76	
77	    /// Run the `check_anchors` op.
78	    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
79	        check_anchors(ctx, params)
80	    }
81	}
