93	/// A heading's GitHub anchor.
94	///
95	/// The algorithm [Markdown anchor
96	/// links](../agent-data/notes.md#markdown-anchor-links) documents:
97	/// lowercase, drop every character that is not alphanumeric, a
98	/// hyphen, or an underscore, and map each remaining space to one
99	/// hyphen. Adjacent spaces are not collapsed, so `a + b` slugs to
100	/// `a--b` while `a: b` slugs to `a-b`.
101	pub fn anchor_slug(heading: &str) -> String {
102	    heading
103	        .chars()
104	        .filter_map(|c| match c {
105	            'a'..='z' | '0'..='9' | '-' | '_' => Some(c),
106	            'A'..='Z' => Some(c.to_ascii_lowercase()),
107	            ' ' => Some('-'),
108	            _ => None,
109	        })
110	        .collect()
111	}
112	
113	/// Blank out code spans in one line, keeping its length so column
114	/// arithmetic still lines up.
115	///
116	/// Backticks pair left to right. An unpaired backtick opens a span
117	/// that runs to the end of the line, which is the reading that
118	/// errs toward ignoring text rather than inventing a citation in
119	/// it.
120	fn blank_code_spans(line: &str) -> String {
121	    let mut out = String::with_capacity(line.len());
122	    let mut in_span = false;
123	    for c in line.chars() {
124	        if c == '`' {
125	            in_span = !in_span;
126	            out.push(' ');
127	        } else if in_span {
128	            out.push(' ');
129	        } else {
130	            out.push(c);
131	        }
132	    }
133	    out
134	}
135	
136	/// The file's lines with fenced blocks and code spans blanked, so
137	/// every later scan sees prose only.
138	fn prose_lines(content: &str) -> Vec<String> {
139	    let mut out = Vec::new();
140	    let mut in_fence = false;
141	    for line in content.lines() {
142	        if line.trim_start().starts_with("```") {
143	            in_fence = !in_fence;
144	            out.push(String::new());
145	            continue;
146	        }
147	        if in_fence {
148	            out.push(String::new());
149	            continue;
150	        }
151	        out.push(blank_code_spans(line));
152	    }
153	    out
154	}
155	
156	/// Collect `(slug, line)` for every heading, in document order.
157	fn headings(lines: &[String]) -> Vec<(String, usize)> {
158	    let mut out = Vec::new();
159	    for (i, line) in lines.iter().enumerate() {
160	        let Some(rest) = line.strip_prefix('#') else {
161	            continue;
162	        };
163	        let text = rest.trim_start_matches('#');
164	        // `#foo` is not a heading, `# foo` is.
165	        if !text.starts_with(' ') {
166	            continue;
167	        }
168	        out.push((anchor_slug(text.trim()), i + 1));
169	    }
170	    out
171	}
172	
173	/// One anchor target found in the prose.
174	struct Target {
175	    slug: String,
176	    line: usize,
177	    /// The file the target names, `None` when it names this one.
178	    /// A named file's slug belongs to that file's headings, which
179	    /// this check does not resolve.
180	    file: Option<String>,
181	}
182	
183	/// Every anchor target naming another file, as `(file, slug, line)`.
184	///
185	/// The check itself resolves none of these. A caller that knows the
186	/// other file can: `config --validate` resolves a config's
187	/// `vc-config.md#<anchor>` links against the schema, since build.rs
188	/// derives those anchors from the key paths.
189	pub fn cross_file_targets(content: &str) -> Vec<(String, String, usize)> {
190	    anchor_targets(&prose_lines(content))
191	        .into_iter()
192	        .filter_map(|t| t.file.map(|f| (f, t.slug, t.line)))
193	        .collect()
