156	/// Collect `(slug, line)` for every heading, in document order.
157	fn headings(lines: &[String]) -> Vec<(String, usize)> {
158	    let mut out = Vec::new();
159	    for (i, line) in lines.iter().enumerate() {
160	        let Some(rest) = line.strip_prefix('#') else {
161	            continue;
162	        };
163	        let text = rest.trim_start_matches('#');
164	        // `#foo` is not a heading, `# foo` is.
165	        if !text.starts_with(' ') {
166	            continue;
167	        }
168	        out.push((anchor_slug(text.trim()), i + 1));
169	    }
170	    out
171	}
