361	/// Check one markdown file's own links, returning every finding in
362	/// document order beside the tally of what was checked.
363	///
364	/// Pure: the caller reads the file and reports. See the module doc
365	/// for the three checks.
366	pub fn analyze(content: &str) -> Report {
367	    let lines = prose_lines(content);
368	    let mut findings: Vec<Finding> = Vec::new();
369	    let mut sites: Vec<Site> = Vec::new();
370	    let mut counts = Counts::default();
371	
372	    let heads = headings(&lines);
373	    let slugs: BTreeSet<&str> = heads.iter().map(|(s, _)| s.as_str()).collect();
374	    counts.headings = heads.len();
375	
376	    let mut seen: BTreeMap<&str, usize> = BTreeMap::new();
377	    for (slug, line) in &heads {
378	        sites.push(Site {
379	            line: *line,
380	            detail: format!("heading slugs to '#{slug}'"),
381	        });
382	        if let Some(first) = seen.get(slug.as_str()) {
383	            findings.push(Finding {
384	                line: *line,
385	                message: format!(
386	                    "duplicate heading anchor '#{slug}', first at line {first}: a link to it \
387	                     reaches the first heading only"
388	                ),
389	            });
390	        } else {
391	            seen.insert(slug.as_str(), *line);
392	        }
393	    }
394	
395	    for target in anchor_targets(&lines) {
396	        let Target { slug, line, file } = target;
397	        if file.is_some() {
398	            counts.anchors_cross_file += 1;
399	            sites.push(Site {
400	                line,
401	                detail: format!("'#{slug}' names another file, not resolved"),
402	            });
403	            continue;
404	        }
405	        counts.anchors_checked += 1;
406	        if slugs.contains(slug.as_str()) {
407	            sites.push(Site {
408	                line,
409	                detail: format!("'#{slug}' resolves"),
410	            });
411	            continue;
412	        }
413	        counts.anchors_failed += 1;
414	        let message = match nearest_slug(&slug, slugs.iter().copied()) {
415	            Some(near) => {
416	                format!("'#{slug}' matches no heading in this file. Did you mean '#{near}'?")
417	            }
418	            None => format!("'#{slug}' matches no heading in this file"),
419	        };
420	        sites.push(Site {
421	            line,
422	            detail: format!("'#{slug}' does not resolve"),
423	        });
424	        findings.push(Finding { line, message });
425	    }
426	
427	    let mut defined: BTreeMap<u32, usize> = BTreeMap::new();
428	    for (i, line) in lines.iter().enumerate() {
429	        if let Some(n) = ref_def_number(line) {
430	            defined.insert(n, i + 1);
431	        }
432	    }
433	    let mut cited: BTreeMap<u32, usize> = BTreeMap::new();
434	    for (i, line) in lines.iter().enumerate() {
435	        for n in citations(line) {
436	            cited.entry(n).or_insert(i + 1);
437	        }
438	    }
439	    counts.refs_defined = defined.len();
440	    counts.refs_cited = cited.len();
441	    for (n, line) in &cited {
442	        if defined.contains_key(n) {
443	            sites.push(Site {
444	                line: *line,
445	                detail: format!("[[{n}]] has a definition"),
446	            });
447	            continue;
448	        }
449	        findings.push(Finding {
450	            line: *line,
451	            message: format!("[[{n}]] is cited but never defined"),
452	        });
453	    }
454	    for (n, line) in &defined {
455	        if !cited.contains_key(n) {
456	            findings.push(Finding {
457	                line: *line,
458	                message: format!("[{n}] is defined but never cited"),
459	            });
460	        }
461	    }
462	
463	    findings.sort_by_key(|f| f.line);
464	    sites.sort_by_key(|s| s.line);
465	    Report {
466	        findings,
467	        sites,
468	        counts,
469	    }
470	}
