472	/// Directories the default set never descends into.
473	///
474	/// Build output and the two repo internals hold no records, and
475	/// `.claude` is the agent repo, whose session data is a journal
476	/// rather than a record. `notes/chores` is frozen history, which
477	/// nothing edits, so a finding there names a file no commit may
478	/// touch ([Frozen
479	/// history](../agent-data/notes.md#frozen-history-chores-and-done)).
480	const SKIP_DIRS: &[&str] = &["target", ".git", ".jj", ".claude", "tmp", "chores"];
481	
482	/// Files the default set skips for the same frozen-history reason
483	/// as `notes/chores`.
484	const SKIP_FILES: &[&str] = &["done.md"];
485	
486	/// Markdown files to check when the caller named none: every `.md`
487	/// under `root` that a commit may still edit.
488	///
489	/// Naming a file explicitly checks it regardless, which is how the
490	/// frozen history is read when someone wants it.
491	fn default_files(root: &Path) -> Vec<PathBuf> {
492	    fn walk(dir: &Path, out: &mut Vec<PathBuf>) {
493	        let Ok(entries) = std::fs::read_dir(dir) else {
494	            return;
495	        };
496	        for entry in entries.flatten() {
497	            let path = entry.path();
498	            let name = entry.file_name();
499	            let name = name.to_string_lossy();
500	            if path.is_dir() {
501	                if SKIP_DIRS.contains(&name.as_ref()) {
502	                    continue;
503	                }
504	                walk(&path, out);
505	            } else if name.ends_with(".md") && !SKIP_FILES.contains(&name.as_ref()) {
506	                out.push(path);
507	            }
508	        }
509	    }
510	    let mut out = Vec::new();
511	    walk(root, &mut out);
512	    out.sort();
513	    out
514	}
