516	/// Run the `check anchors` subcommand: check each file's own
517	/// links and report every finding, erroring when any was found.
518	///
519	/// `ctx` is unused: the check reads plain files and neither the
520	/// user config nor the `--log` path applies. It is present for the
521	/// uniform subcommand-layer signature.
522	pub fn check_anchors(
523	    _ctx: &Context,
524	    params: &CheckAnchorsParams,
525	) -> Result<(), Box<dyn std::error::Error>> {
526	    debug!("check anchors: enter");
527	    let files = if params.files.is_empty() {
528	        let root = crate::common::find_workspace_root()
529	            .ok_or("not inside a workspace: name the files to check")?;
530	        default_files(&root)
531	    } else {
532	        params.files.clone()
533	    };
534	
535	    let mut total = Counts::default();
536	    let mut findings = 0usize;
537	    for file in &files {
538	        let content = std::fs::read_to_string(file)
539	            .map_err(|e| format!("cannot read {}: {e}", file.display()))?;
540	        let report = analyze(&content);
541	        for site in &report.sites {
542	            trace!("{}:{}: {}", file.display(), site.line, site.detail);
543	        }
544	        for finding in &report.findings {
545	            warn!("{}:{}: {}", file.display(), finding.line, finding.message);
546	        }
547	        let c = &report.counts;
548	        debug!(
549	            "{}: {} heading(s), {} link(s) checked, {} failed, {} cross-file, {} ref(s) defined, \
550	             {} cited",
551	            file.display(),
552	            c.headings,
553	            c.anchors_checked,
554	            c.anchors_failed,
555	            c.anchors_cross_file,
556	            c.refs_defined,
557	            c.refs_cited
558	        );
559	        findings += report.findings.len();
560	        total.headings += c.headings;
561	        total.anchors_checked += c.anchors_checked;
562	        total.anchors_failed += c.anchors_failed;
563	        total.anchors_cross_file += c.anchors_cross_file;
564	        total.refs_defined += c.refs_defined;
565	        total.refs_cited += c.refs_cited;
566	    }
567	
568	    let n = files.len();
569	    let word = if n == 1 { "file" } else { "files" };
570	    // The link count is the summary's point: it separates a pass
571	    // that checked something from one that had nothing to check.
572	    let checked = total.anchors_checked + total.refs_cited;
573	    info!(
574	        "check anchors: {n} {word}, {checked} link(s) checked, {} failed, {} cross-file \
575	         skipped, {} heading(s)",
576	        findings, total.anchors_cross_file, total.headings
577	    );
578	    if findings == 0 {
579	        debug!("check anchors: exit");
580	        Ok(())
581	    } else {
582	        debug!("check anchors: exit with findings");
583	        Err(format!("{findings} anchor problem(s) found").into())
584	    }
585	}
